<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref } from 'vue'
import { apiGet, apiPost, apiPut, type ApiError } from './api/client'

type Session={accessToken:string;refreshToken:string;userEmail:string}
type Tenant={id:string;name:string;slug:string;status:string;primary_hostname?:string|null}
type Surface='LANDING'|'BOOKING'
type Scope='GLOBAL'|'SELECTED'|'EXCLUSIVE'|'INTERNAL'
type Status='DRAFT'|'PUBLISHED'|'INACTIVE'
type TemplateRow={id:string;surface:Surface;key:string;name:string;description?:string|null;segment?:string|null;status:Status;scope:Scope;default_for_new_tenants:boolean;exclusive_tenant_id?:string|null;selected_tenant_ids?:string[];latest_version:number;published_version?:number|null;versions?:TemplateVersion[]}
type TemplateVersion={id:string;version_number:number;published:boolean;changelog?:string|null;created_at?:string}
type TemplateContentResponse={id:string;surface:Surface;key:string;name:string;version:{id:string;version_number:number;content:Record<string,any>;published:boolean}}
type LandingState={slug:string;status:string;template_key?:string|null;version_number?:number|null;content?:PageContent;draft_version_id?:string|null;current_version_id?:string|null}
type PageBlock={id:string;type:string;props:Record<string,any>;style?:Record<string,any>;responsive?:Record<string,any>}
type PageContent={version:number;title?:string;global_styles:Record<string,any>;seo:Record<string,any>;blocks:PageBlock[]}
type BookingParameters={service_mode:string;email_mode:string;phone_mode:string;duration_mode:string;professional_mode:string;default_duration_minutes:number;default_professional_name:string;default_customer_mode:string;simultaneous:{public:boolean;internal:boolean;capacity:number;enforce_public:boolean;enforce_internal:boolean};rules:{enforce_business_hours:boolean;enforce_blocked_periods:boolean};minimum_notice_minutes:number;phone:{country:string;country_code:string;area_code:string;add_ninth_digit:boolean}}
type BrandingManifest={app:{public_name:string;slogan?:string};theme:{colors:{primary:string;secondary:string;accent:string;background:string;text:string};mode:string};settings?:Record<string,unknown>}

type Panel='support'|'templates'
type SupportTab='agenda'|'landing'|'booking'|'branding'
const storageKey='scheduler-pro-admin-session'
const open=ref(false),loading=ref(false),saving=ref(false),error=ref(''),toast=ref('')
const panel=ref<Panel>('support'),supportTab=ref<SupportTab>('agenda'),templateSurface=ref<Surface>('LANDING')
const session=ref<Session|null>(null),tenants=ref<Tenant[]>([]),tenantId=ref('')
const bookingParams=ref<BookingParameters|null>(null),landing=ref<LandingState|null>(null),branding=ref<BrandingManifest|null>(null)
const availableLanding=ref<TemplateRow[]>([]),availableBooking=ref<TemplateRow[]>([]),templates=ref<TemplateRow[]>([])
const selectedTemplateId=ref(''),selectedTemplate=ref<TemplateRow|null>(null),templateContent=ref<Record<string,any>>({})
const createForm=ref({surface:'LANDING' as Surface,key:'',name:'',description:'',segment:'',scope:'INTERNAL' as Scope,status:'DRAFT' as Status,default_for_new_tenants:false,exclusive_tenant_id:'',selected_tenant_ids:[] as string[]})
const duplicateForm=ref({key:'',name:''})
const newBlockType=ref('text')

const selectedTenant=computed(()=>tenants.value.find(item=>item.id===tenantId.value)||null)
const pageContent=computed<PageContent|null>(()=>{const value=panel.value==='templates'?templateContent.value:landing.value?.content;return value&&Array.isArray(value.blocks)?value as PageContent:null})
const token=()=>session.value?.accessToken||''
const authenticated=computed(()=>Boolean(token()))

function readSession(){const raw=localStorage.getItem(storageKey);if(!raw){session.value=null;return}try{session.value=JSON.parse(raw) as Session}catch{session.value=null}}
function message(value:string){toast.value=value;window.setTimeout(()=>{if(toast.value===value)toast.value=''},3500)}
function describe(exc:unknown,fallback:string){const value=exc as Partial<ApiError>;return value?.message||fallback}
function uid(type:string){return `${type}-${Date.now().toString(36)}-${Math.random().toString(36).slice(2,7)}`}
function clone<T>(value:T):T{return JSON.parse(JSON.stringify(value)) as T}
function normalizePage(value:Record<string,any>|undefined|null):PageContent{return{version:Number(value?.version||2),title:String(value?.title||''),global_styles:{primary:'#3151cf',secondary:'#151c31',accent:'#6d72ef',background:'#ffffff',text:'#1d273a',...(value?.global_styles||{})},seo:{...(value?.seo||{})},blocks:Array.isArray(value?.blocks)?value!.blocks.map((block:any)=>({...block,id:block.id||uid(block.type||'text'),type:block.type||'text',props:block.props||{},style:block.style||{},responsive:block.responsive||{desktop:{},tablet:{},mobile:{},hidden:{desktop:false,tablet:false,mobile:false}}})):[]}}
function defaultBlock(type:string):PageBlock{const defaults:Record<string,Record<string,any>>={hero:{eyebrow:'Seu negócio',title:'Apresente sua proposta de valor',text:'Conte de forma objetiva por que o cliente deve escolher você.',cta:'Agendar agora',image:''},text:{title:'Nova seção',text:'Escreva o conteúdo aqui.'},services:{title:'Serviços',subtitle:'Conheça as opções',show_prices:true},professionals:{title:'Profissionais',layout:'cards'},gallery:{title:'Galeria',layout:'grid',images:[]},cards:{title:'Diferenciais',items:[{title:'Diferencial 1',text:'Descrição.'}]},business_hours:{title:'Horários de atendimento'},booking:{title:'Escolha seu horário',subtitle:'Agende em poucos passos.'},contact:{title:'Contato',phone:'',email:''},footer:{text:'Obrigado pela visita.'}};return{id:uid(type),type,props:clone(defaults[type]||{title:'Novo bloco'}),style:{},responsive:{desktop:{},tablet:{},mobile:{},hidden:{desktop:false,tablet:false,mobile:false}}}}
function addBlock(){const content=pageContent.value;if(!content)return;content.blocks.push(defaultBlock(newBlockType.value))}
function moveBlock(index:number,delta:number){const content=pageContent.value;if(!content)return;const target=index+delta;if(target<0||target>=content.blocks.length)return;const [item]=content.blocks.splice(index,1);if(item)content.blocks.splice(target,0,item)}
function removeBlock(index:number){pageContent.value?.blocks.splice(index,1)}
function duplicateBlock(index:number){const content=pageContent.value;if(!content)return;const source=content.blocks[index];if(!source)return;const copy=clone(source);copy.id=uid(copy.type);content.blocks.splice(index+1,0,copy)}
function color(key:string){return String(pageContent.value?.global_styles?.[key]||'#3151cf')}
function setColor(key:string,value:string){if(pageContent.value)pageContent.value.global_styles[key]=value}

async function loadTenants(){readSession();if(!authenticated.value)return;tenants.value=await apiGet<Tenant[]>('/platform/tenants',token());if(!tenantId.value&&tenants.value.length)tenantId.value=tenants.value[0]!.id}
async function loadSupport(){if(!tenantId.value)return;loading.value=true;error.value='';try{const [params,state,brand,landingTemplates,bookingTemplates]=await Promise.all([apiGet<BookingParameters>(`/platform/tenant-support/${tenantId.value}/booking-parameters`,token()),apiGet<LandingState>(`/platform/tenant-support/${tenantId.value}/landing/home`,token()),apiGet<BrandingManifest>(`/platform/tenant-support/${tenantId.value}/branding`,token()),apiGet<TemplateRow[]>(`/platform/templates/available/${tenantId.value}?surface=LANDING`,token()),apiGet<TemplateRow[]>(`/platform/templates/available/${tenantId.value}?surface=BOOKING`,token())]);bookingParams.value=params;landing.value={...state,content:normalizePage(state.content as Record<string,any>)};branding.value=brand;availableLanding.value=landingTemplates;availableBooking.value=bookingTemplates}catch(exc){error.value=describe(exc,'Não foi possível abrir o suporte deste cliente.')}finally{loading.value=false}}
async function loadTemplates(){loading.value=true;error.value='';try{templates.value=await apiGet<TemplateRow[]>(`/platform/templates?surface=${templateSurface.value}`,token());if(selectedTemplateId.value&&!templates.value.some(item=>item.id===selectedTemplateId.value)){selectedTemplateId.value='';selectedTemplate.value=null}}catch(exc){error.value=describe(exc,'Falha ao carregar modelos globais.')}finally{loading.value=false}}
async function openCenter(){readSession();if(!authenticated.value)return;open.value=true;await loadTenants();if(panel.value==='support')await loadSupport();else await loadTemplates()}
function close(){open.value=false;error.value=''}
async function switchPanel(value:Panel){panel.value=value;if(value==='support')await loadSupport();else await loadTemplates()}
async function selectTenant(){await loadSupport()}
async function saveAgenda(){if(!bookingParams.value)return;saving.value=true;error.value='';try{bookingParams.value=await apiPut<BookingParameters>(`/platform/tenant-support/${tenantId.value}/booking-parameters`,bookingParams.value,token());message('Modelo de negócio da Agenda atualizado pelo Control Plane.')}catch(exc){error.value=describe(exc,'Falha ao salvar as regras da Agenda.')}finally{saving.value=false}}
async function saveLanding(publish=false){if(!landing.value?.content)return;saving.value=true;error.value='';try{const draft=await apiPost<{version_id:string}>(`/platform/tenant-support/${tenantId.value}/landing/home/draft`,landing.value.content,token());landing.value.draft_version_id=draft.version_id;if(publish)await apiPost(`/platform/tenant-support/${tenantId.value}/landing/home/publish`,{version_id:draft.version_id},token());message(publish?'Landing salva e publicada.':'Rascunho da Landing salvo.');await loadSupport()}catch(exc){error.value=describe(exc,'Falha ao salvar a Landing Page.')}finally{saving.value=false}}
async function applyLandingTemplate(row:TemplateRow,publish=false){saving.value=true;error.value='';try{await apiPost(`/platform/tenant-support/${tenantId.value}/landing/home/apply-global-template`,{template_id:row.id,version_number:row.published_version||row.latest_version,publish},token());message(`Modelo ${row.name} aplicado ao cliente sem alterar o modelo global.`);await loadSupport()}catch(exc){error.value=describe(exc,'Falha ao aplicar o modelo.')}finally{saving.value=false}}
async function applyBookingTemplate(row:TemplateRow){saving.value=true;error.value='';try{await apiPost(`/platform/tenant-support/${tenantId.value}/booking-page/apply-global-template`,{template_id:row.id,version_number:row.published_version||row.latest_version,publish:true},token());message(`Modelo de agendamento ${row.name} aplicado.`)}catch(exc){error.value=describe(exc,'Falha ao aplicar o modelo da página de agendamento.')}finally{saving.value=false}}
async function saveBranding(){if(!branding.value)return;saving.value=true;error.value='';try{const payload={public_name:branding.value.app.public_name,slogan:branding.value.app.slogan||null,primary_color:branding.value.theme.colors.primary,secondary_color:branding.value.theme.colors.secondary,accent_color:branding.value.theme.colors.accent,background_color:branding.value.theme.colors.background,text_color:branding.value.theme.colors.text,theme_mode:branding.value.theme.mode,settings:branding.value.settings||{}};await apiPut(`/platform/tenant-support/${tenantId.value}/branding`,payload,token());message('Identidade visual atualizada.');await loadSupport()}catch(exc){error.value=describe(exc,'Falha ao salvar a identidade.')}finally{saving.value=false}}

async function createTemplate(){saving.value=true;error.value='';try{const content=createForm.value.surface==='LANDING'?normalizePage({version:2,global_styles:{primary:'#3151cf',secondary:'#151c31',accent:'#6d72ef',background:'#ffffff',text:'#1d273a',radius:16},seo:{},blocks:[defaultBlock('hero'),defaultBlock('services'),defaultBlock('booking'),defaultBlock('footer')]}):{version:1,surface:'BOOKING',global_styles:{primary:'#3151cf',secondary:'#151c31',accent:'#6d72ef',background:'#f7f8fc',surface:'#ffffff',text:'#1d273a',muted:'#64748b',radius:18},layout:{hero:true,service_selector:'cards',professional_selector:'cards',calendar:'month_days',time_selector:'chips',customer_form:'compact',mobile_sticky_action:true},copy:{eyebrow:'Agendamento online',title:'Escolha seu horário',subtitle:'Selecione o atendimento e encontre a melhor disponibilidade.',success:'Seu horário foi reservado.'}};const created=await apiPost<TemplateRow>('/platform/templates',{...createForm.value,exclusive_tenant_id:createForm.value.exclusive_tenant_id||null,content,changelog:'Versão inicial'},token());message('Modelo global criado.');createForm.value={surface:templateSurface.value,key:'',name:'',description:'',segment:'',scope:'INTERNAL',status:'DRAFT',default_for_new_tenants:false,exclusive_tenant_id:'',selected_tenant_ids:[]};await loadTemplates();await selectTemplate(created.id)}catch(exc){error.value=describe(exc,'Falha ao criar modelo.')}finally{saving.value=false}}
async function selectTemplate(id:string){selectedTemplateId.value=id;if(!id){selectedTemplate.value=null;templateContent.value={};return}loading.value=true;try{const detail=await apiGet<TemplateRow>(`/platform/templates/${id}`,token());selectedTemplate.value=detail;const version=detail.latest_version||detail.versions?.[0]?.version_number||0;if(version){const response=await apiGet<TemplateContentResponse>(`/platform/templates/${id}/versions/${version}/content`,token());templateContent.value=response.surface==='LANDING'?normalizePage(response.version.content):clone(response.version.content)}else templateContent.value={}}catch(exc){error.value=describe(exc,'Falha ao abrir o modelo.')}finally{loading.value=false}}
async function saveTemplateMetadata(){if(!selectedTemplate.value)return;saving.value=true;try{selectedTemplate.value=await apiPut<TemplateRow>(`/platform/templates/${selectedTemplate.value.id}`,{name:selectedTemplate.value.name,description:selectedTemplate.value.description,segment:selectedTemplate.value.segment,status:selectedTemplate.value.status,scope:selectedTemplate.value.scope,default_for_new_tenants:selectedTemplate.value.default_for_new_tenants,exclusive_tenant_id:selectedTemplate.value.exclusive_tenant_id||null,selected_tenant_ids:selectedTemplate.value.selected_tenant_ids||[]},token());message('Metadados do modelo salvos.');await loadTemplates()}catch(exc){error.value=describe(exc,'Falha ao salvar o modelo.')}finally{saving.value=false}}
async function createTemplateVersion(publish=false){if(!selectedTemplate.value)return;saving.value=true;try{const result=await apiPost<{version_number:number}>(`/platform/templates/${selectedTemplate.value.id}/versions`,{content:templateContent.value,changelog:'Edição pelo Control Plane',publish},token());message(publish?`Versão ${result.version_number} criada e publicada.`:`Versão ${result.version_number} criada como rascunho.`);await loadTemplates();await selectTemplate(selectedTemplate.value.id)}catch(exc){error.value=describe(exc,'Falha ao versionar o modelo.')}finally{saving.value=false}}
async function duplicateTemplate(){if(!selectedTemplate.value||!duplicateForm.value.key||!duplicateForm.value.name)return;saving.value=true;try{const copy=await apiPost<TemplateRow>(`/platform/templates/${selectedTemplate.value.id}/duplicate`,duplicateForm.value,token());duplicateForm.value={key:'',name:''};message('Modelo duplicado como rascunho interno.');await loadTemplates();await selectTemplate(copy.id)}catch(exc){error.value=describe(exc,'Falha ao duplicar o modelo.')}finally{saving.value=false}}

function refreshSession(){const was=authenticated.value;readSession();if(!was&&authenticated.value&&open.value)void openCenter()}
onMounted(()=>{readSession();window.addEventListener('storage',refreshSession);window.addEventListener('scheduler-pro-admin-auth-changed',refreshSession)})
onUnmounted(()=>{window.removeEventListener('storage',refreshSession);window.removeEventListener('scheduler-pro-admin-auth-changed',refreshSession)})
</script>

<template>
  <button v-if="authenticated" class="admin-support-launcher" type="button" @click="openCenter"><span>✦</span><strong>Modelos & Suporte</strong></button>
  <div v-if="open&&authenticated" class="admin-support-backdrop" @click.self="close">
    <section class="admin-support-center">
      <header class="support-topbar"><div><span>Scheduler Pro · Control Plane</span><h2>Modelos & Suporte ao Cliente</h2><p>Administre modelos globais e configure diretamente o ambiente isolado de cada cliente.</p></div><button class="close" @click="close">×</button></header>
      <nav class="support-main-tabs"><button :class="{active:panel==='support'}" @click="switchPanel('support')">Suporte ao cliente</button><button :class="{active:panel==='templates'}" @click="switchPanel('templates')">Biblioteca de modelos</button></nav>
      <p v-if="toast" class="support-ok">{{toast}}</p><p v-if="error" class="support-error">{{error}}</p><div v-if="loading" class="support-loading"><RefreshCw class="spin"/>Atualizando dados...</div>

      <main v-else-if="panel==='support'" class="support-body">
        <aside class="support-sidebar"><label>Cliente<select v-model="tenantId" @change="selectTenant"><option v-for="item in tenants" :key="item.id" :value="item.id">{{item.name}} · {{item.slug}}</option></select></label><div v-if="selectedTenant" class="tenant-summary"><strong>{{selectedTenant.name}}</strong><span>{{selectedTenant.primary_hostname||selectedTenant.slug}}</span><em>{{selectedTenant.status}}</em></div><button :class="{active:supportTab==='agenda'}" @click="supportTab='agenda'">Modelo de negócio da Agenda</button><button :class="{active:supportTab==='landing'}" @click="supportTab='landing'">Landing Page</button><button :class="{active:supportTab==='booking'}" @click="supportTab='booking'">Página de Agendamento</button><button :class="{active:supportTab==='branding'}" @click="supportTab='branding'">Identidade visual</button></aside>
        <section class="support-workspace">
          <template v-if="supportTab==='agenda'&&bookingParams"><header class="workspace-head"><div><span>Agenda</span><h3>Modelo de negócio</h3><p>Os mesmos parâmetros usados pelo cliente, administrados aqui sem acessar a conta dele.</p></div><button class="primary" :disabled="saving" @click="saveAgenda">Salvar regras</button></header><div class="support-form-grid"><label>Serviço<select v-model="bookingParams.service_mode"><option value="REQUIRED">Obrigatório</option><option value="OPTIONAL">Opcional</option><option value="DISABLED">Oculto</option></select></label><label>Telefone / WhatsApp<select v-model="bookingParams.phone_mode"><option value="REQUIRED">Obrigatório</option><option value="OPTIONAL">Opcional</option><option value="DISABLED">Oculto</option></select></label><label>E-mail<select v-model="bookingParams.email_mode"><option value="REQUIRED">Obrigatório</option><option value="OPTIONAL">Opcional</option><option value="DISABLED">Oculto</option></select></label><label>Profissional / responsável<select v-model="bookingParams.professional_mode"><option value="REQUIRED">Obrigatório</option><option value="OPTIONAL">Opcional</option><option value="DISABLED">Oculto</option></select></label><label>Tempo / duração<select v-model="bookingParams.duration_mode"><option value="REQUIRED">Obrigatório</option><option value="OPTIONAL">Opcional</option><option value="DISABLED">Oculto</option></select></label><label>Duração interna padrão<input v-model.number="bookingParams.default_duration_minutes" type="number" min="5" max="720"/></label><label>Responsável padrão<input v-model="bookingParams.default_professional_name" placeholder="Ex.: Roberto Martelinho de Ouro"/></label><label>Abertura do Operador<select v-model="bookingParams.default_customer_mode"><option value="NEW">Novo cliente</option><option value="EXISTING">Cliente existente</option></select></label><label>Capacidade simultânea<input v-model.number="bookingParams.simultaneous.capacity" type="number" min="1" max="10000"/></label><label class="check"><input v-model="bookingParams.simultaneous.enforce_internal" type="checkbox"/>Aplicar limite no Operador</label><label class="check"><input v-model="bookingParams.simultaneous.enforce_public" type="checkbox"/>Aplicar limite na página pública</label><label class="check"><input v-model="bookingParams.rules.enforce_business_hours" type="checkbox"/>Restringir pelo expediente</label><label class="check"><input v-model="bookingParams.rules.enforce_blocked_periods" type="checkbox"/>Respeitar bloqueios</label><label>Antecedência mínima (min)<input v-model.number="bookingParams.minimum_notice_minutes" type="number" min="0"/></label></div></template>

          <template v-else-if="supportTab==='landing'&&landing?.content"><header class="workspace-head"><div><span>Landing Page</span><h3>Editor administrativo</h3><p>Edite o rascunho do cliente ou aplique uma versão global como cópia independente.</p></div><div><button @click="saveLanding(false)">Salvar rascunho</button><button class="primary" @click="saveLanding(true)">Salvar e publicar</button></div></header><div class="template-picker"><strong>Modelos globais disponíveis</strong><div><button v-for="item in availableLanding" :key="item.id" @click="applyLandingTemplate(item,false)"><span>{{item.name}}</span><small>{{item.segment||'geral'}} · v{{item.published_version||item.latest_version}}</small></button></div></div><div class="visual-editor"><div class="editor-controls"><strong>Identidade</strong><label>Primária<input type="color" :value="color('primary')" @input="setColor('primary',($event.target as HTMLInputElement).value)"/></label><label>Secundária<input type="color" :value="color('secondary')" @input="setColor('secondary',($event.target as HTMLInputElement).value)"/></label><label>Fundo<input type="color" :value="color('background')" @input="setColor('background',($event.target as HTMLInputElement).value)"/></label><label>Texto<input type="color" :value="color('text')" @input="setColor('text',($event.target as HTMLInputElement).value)"/></label><div class="add-block"><select v-model="newBlockType"><option v-for="value in ['hero','text','services','professionals','gallery','cards','business_hours','booking','contact','footer']" :key="value">{{value}}</option></select><button @click="addBlock">Adicionar bloco</button></div></div><div class="block-editor"><article v-for="(block,index) in landing.content.blocks" :key="block.id"><header><strong>{{block.type}}</strong><div><button :disabled="index===0" @click="moveBlock(index,-1)">↑</button><button :disabled="index===landing.content.blocks.length-1" @click="moveBlock(index,1)">↓</button><button @click="duplicateBlock(index)">Duplicar</button><button class="danger" @click="removeBlock(index)">Excluir</button></div></header><label v-if="'eyebrow' in block.props">Chamada<input v-model="block.props.eyebrow"/></label><label v-if="'title' in block.props">Título<input v-model="block.props.title"/></label><label v-if="'subtitle' in block.props">Subtítulo<textarea v-model="block.props.subtitle"/></label><label v-if="'text' in block.props">Texto<textarea v-model="block.props.text"/></label><label v-if="'cta' in block.props">Botão<input v-model="block.props.cta"/></label></article></div><div class="live-preview" :style="{'--p':landing.content.global_styles.primary,'--s':landing.content.global_styles.secondary,'--bg':landing.content.global_styles.background,'--txt':landing.content.global_styles.text}"><section v-for="block in landing.content.blocks" :key="block.id" :class="`preview-${block.type}`"><small v-if="block.props.eyebrow">{{block.props.eyebrow}}</small><h2>{{block.props.title||block.props.text||block.type}}</h2><p v-if="block.props.subtitle||block.props.text">{{block.props.subtitle||block.props.text}}</p><button v-if="block.props.cta">{{block.props.cta}}</button><div v-if="['services','professionals','gallery','cards'].includes(block.type)" class="preview-cards"><i v-for="n in 3" :key="n"></i></div></section></div></div></template>

          <template v-else-if="supportTab==='booking'"><header class="workspace-head"><div><span>Página de Agendamento</span><h3>Modelo visual</h3><p>Aplique uma versão global sem alterar o modelo original.</p></div></header><div class="booking-template-grid"><article v-for="item in availableBooking" :key="item.id"><span>{{item.segment||'geral'}}</span><h4>{{item.name}}</h4><p>{{item.description}}</p><small>Versão {{item.published_version||item.latest_version}}</small><button class="primary" @click="applyBookingTemplate(item)">Aplicar ao cliente</button></article><div v-if="!availableBooking.length" class="empty">Nenhum modelo publicado para este cliente.</div></div></template>

          <template v-else-if="supportTab==='branding'&&branding"><header class="workspace-head"><div><span>Identidade</span><h3>Marca e aparência</h3><p>As alterações são salvas no perfil do cliente e não afetam outros ambientes.</p></div><button class="primary" @click="saveBranding">Salvar identidade</button></header><div class="support-form-grid"><label>Nome público<input v-model="branding.app.public_name"/></label><label>Slogan<input v-model="branding.app.slogan"/></label><label>Cor primária<input v-model="branding.theme.colors.primary" type="color"/></label><label>Cor secundária<input v-model="branding.theme.colors.secondary" type="color"/></label><label>Cor de destaque<input v-model="branding.theme.colors.accent" type="color"/></label><label>Fundo<input v-model="branding.theme.colors.background" type="color"/></label><label>Texto<input v-model="branding.theme.colors.text" type="color"/></label></div></template>
        </section>
      </main>

      <main v-else class="templates-body">
        <aside class="templates-sidebar"><div class="surface-toggle"><button :class="{active:templateSurface==='LANDING'}" @click="templateSurface='LANDING';loadTemplates()">Landing Pages</button><button :class="{active:templateSurface==='BOOKING'}" @click="templateSurface='BOOKING';loadTemplates()">Páginas de Agendamento</button></div><select v-model="selectedTemplateId" @change="selectTemplate(selectedTemplateId)"><option value="">Novo modelo</option><option v-for="item in templates" :key="item.id" :value="item.id">{{item.name}} · {{item.status}}</option></select><template v-if="!selectedTemplate"><h3>Criar modelo</h3><label>Chave<input v-model="createForm.key" placeholder="meu-modelo"/></label><label>Nome<input v-model="createForm.name"/></label><label>Descrição<textarea v-model="createForm.description"/></label><label>Segmento<input v-model="createForm.segment"/></label><label>Escopo<select v-model="createForm.scope"><option value="INTERNAL">Interno</option><option value="GLOBAL">Todos os clientes</option><option value="SELECTED">Clientes selecionados</option><option value="EXCLUSIVE">Exclusivo</option></select></label><label v-if="createForm.scope==='EXCLUSIVE'">Cliente<select v-model="createForm.exclusive_tenant_id"><option value="">Selecione</option><option v-for="item in tenants" :key="item.id" :value="item.id">{{item.name}}</option></select></label><button class="primary full" @click="createTemplate">Criar modelo</button></template><template v-else><h3>{{selectedTemplate.name}}</h3><label>Nome<input v-model="selectedTemplate.name"/></label><label>Descrição<textarea v-model="selectedTemplate.description"/></label><label>Status<select v-model="selectedTemplate.status"><option value="DRAFT">Rascunho</option><option value="PUBLISHED">Publicado</option><option value="INACTIVE">Inativo</option></select></label><label>Escopo<select v-model="selectedTemplate.scope"><option value="INTERNAL">Interno</option><option value="GLOBAL">Todos</option><option value="SELECTED">Selecionados</option><option value="EXCLUSIVE">Exclusivo</option></select></label><button class="full" @click="saveTemplateMetadata">Salvar metadados</button><hr/><label>Nova chave da cópia<input v-model="duplicateForm.key"/></label><label>Nome da cópia<input v-model="duplicateForm.name"/></label><button class="full" @click="duplicateTemplate">Duplicar modelo</button></template></aside>
        <section class="template-editor-workspace"><template v-if="selectedTemplate"><header class="workspace-head"><div><span>{{selectedTemplate.surface}}</span><h3>{{selectedTemplate.name}} · versão {{selectedTemplate.latest_version}}</h3><p>Criar uma nova versão nunca altera automaticamente clientes que usam versões anteriores.</p></div><div><button @click="createTemplateVersion(false)">Criar versão</button><button class="primary" @click="createTemplateVersion(true)">Criar e publicar</button></div></header><template v-if="selectedTemplate.surface==='LANDING'&&pageContent"><div class="visual-editor"><div class="editor-controls"><strong>Identidade global</strong><label>Primária<input type="color" :value="color('primary')" @input="setColor('primary',($event.target as HTMLInputElement).value)"/></label><label>Secundária<input type="color" :value="color('secondary')" @input="setColor('secondary',($event.target as HTMLInputElement).value)"/></label><label>Fundo<input type="color" :value="color('background')" @input="setColor('background',($event.target as HTMLInputElement).value)"/></label><label>Texto<input type="color" :value="color('text')" @input="setColor('text',($event.target as HTMLInputElement).value)"/></label><div class="add-block"><select v-model="newBlockType"><option v-for="value in ['hero','text','services','professionals','gallery','cards','business_hours','booking','contact','footer']" :key="value">{{value}}</option></select><button @click="addBlock">Adicionar bloco</button></div></div><div class="block-editor"><article v-for="(block,index) in pageContent.blocks" :key="block.id"><header><strong>{{block.type}}</strong><div><button @click="moveBlock(index,-1)">↑</button><button @click="moveBlock(index,1)">↓</button><button @click="duplicateBlock(index)">Duplicar</button><button class="danger" @click="removeBlock(index)">Excluir</button></div></header><label v-if="'eyebrow' in block.props">Chamada<input v-model="block.props.eyebrow"/></label><label v-if="'title' in block.props">Título<input v-model="block.props.title"/></label><label v-if="'subtitle' in block.props">Subtítulo<textarea v-model="block.props.subtitle"/></label><label v-if="'text' in block.props">Texto<textarea v-model="block.props.text"/></label><label v-if="'cta' in block.props">Botão<input v-model="block.props.cta"/></label></article></div><div class="live-preview" :style="{'--p':pageContent.global_styles.primary,'--s':pageContent.global_styles.secondary,'--bg':pageContent.global_styles.background,'--txt':pageContent.global_styles.text}"><section v-for="block in pageContent.blocks" :key="block.id" :class="`preview-${block.type}`"><small v-if="block.props.eyebrow">{{block.props.eyebrow}}</small><h2>{{block.props.title||block.props.text||block.type}}</h2><p v-if="block.props.subtitle||block.props.text">{{block.props.subtitle||block.props.text}}</p><button v-if="block.props.cta">{{block.props.cta}}</button><div v-if="['services','professionals','gallery','cards'].includes(block.type)" class="preview-cards"><i v-for="n in 3" :key="n"></i></div></section></div></div></template><template v-else><div class="booking-visual-editor"><div><label>Cor principal<input v-model="templateContent.global_styles.primary" type="color"/></label><label>Cor secundária<input v-model="templateContent.global_styles.secondary" type="color"/></label><label>Fundo<input v-model="templateContent.global_styles.background" type="color"/></label><label>Raio<input v-model.number="templateContent.global_styles.radius" type="number"/></label><label>Título<input v-model="templateContent.copy.title"/></label><label>Subtítulo<textarea v-model="templateContent.copy.subtitle"/></label><label>Mensagem de sucesso<textarea v-model="templateContent.copy.success"/></label></div><div class="booking-preview" :style="{background:templateContent.global_styles.background,color:templateContent.global_styles.text,borderRadius:`${templateContent.global_styles.radius||18}px`}"><span>Agendamento online</span